import urllib.request, ssl, re, xml.etree.ElementTree as ET
from email.utils import parsedate_to_datetime
ssl._create_default_https_context = ssl._create_unverified_context
feeds = {
 'coindesk':'https://www.coindesk.com/arc/outboundfeeds/rss/',
 'cointelegraph':'https://cointelegraph.com/rss',
 'bitcoinmag':'https://bitcoinmagazine.com/.rss/full/',
 'cryptoslate':'https://cryptoslate.com/feed/',
 'newsbtc':'https://www.newsbtc.com/feed/',
 'cryptopotato':'https://cryptopotato.com/feed/',
 'u_today':'https://u.today/rss',
 'dailyhodl':'https://dailyhodl.com/feed/',
}
keywords=['reserve','arma','bitcoin reserve','strategic bitcoin','mark cuban','xrp','coinbase premium','tokenized stocks']
for name,url in feeds.items():
    try:
        data=urllib.request.urlopen(url,timeout=20).read()
        print('\n===',name,url,'bytes',len(data))
        txt=data.decode('utf-8','ignore')
        # rough print of first 8 item titles
        titles=[]
        if '<rss' in txt or '<rdf:RDF' in txt:
            for m in re.finditer(r'<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</title>', txt, re.S|re.I):
                t=re.sub(r'<.*?>','',m.group(1)).strip()
                if t and t not in titles:
                    titles.append(t)
            # skip channel title first
            for t in titles[1:15]:
                if any(k.lower() in t.lower() for k in keywords):
                    print('MATCH',t)
        else:
            for m in re.finditer(r'<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</title>', txt, re.S|re.I):
                t=re.sub(r'<.*?>','',m.group(1)).strip()
                if t and t not in titles:
                    titles.append(t)
            for t in titles[:15]:
                if any(k.lower() in t.lower() for k in keywords):
                    print('MATCH',t)
    except Exception as e:
        print('ERR',name,e)
